import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

interface SheetView {
  id: string;
  today: string;
  archived: boolean;
  lastBatch: number | null;
}

// Who is signed in (a typed name, no password) and which sheet is active. Everything else in the
// app is kept per sheet, so features read the active sheet id from here.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  readonly user = signal<string | null>(null);
  readonly sheetId = signal<string | null>(null);
  /** The active sheet's today (yyyy-mm-dd) as the store holds it. */
  private readonly sheetToday = signal<string | null>(null);
  /** The date this screen shows the sheet as of (yyyy-mm-dd); null while it shows it as it is now.
   *  It belongs to this screen alone: while it is set, everything read is as it stood at the end of
   *  that day, and every change is refused. */
  readonly asOf = signal<string | null>(null);
  /** The active sheet's today (yyyy-mm-dd): every date-dependent decision and default date uses
   *  it, never the real clock; while an as-of date is set, that date stands in for it. */
  readonly today = computed(() => this.asOf() ?? this.sheetToday());
  /** Whether the active sheet is archived: everything stays visible and every change is refused. */
  readonly archived = signal(false);
  /** The number of the active sheet's last settle batch; null when there has been none. */
  readonly lastBatch = signal<number | null>(null);
  /** Counts sheet loads, so features re-read their data even when the same id is loaded again. */
  readonly loads = signal(0);

  signIn(name: string): boolean {
    const trimmed = name.trim();
    if (!trimmed) return false;
    this.user.set(trimmed);
    return true;
  }

  /** Load a sheet by id; a sheet never loaded before starts empty. */
  async loadSheet(id: string): Promise<void> {
    const sheet = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/load`, null),
    );
    this.show(sheet);
    this.loads.update((n) => n + 1);
  }

  /** Show the sheet as of a date (yyyy-mm-dd) on this screen, re-reading everything as it stood then. */
  setAsOf(date: string): void {
    this.asOf.set(date);
    this.loads.update((n) => n + 1);
  }

  /** Show the sheet as it is now again, re-reading everything. */
  clearAsOf(): void {
    this.asOf.set(null);
    this.loads.update((n) => n + 1);
  }

  /** Change the active sheet's today. */
  async setToday(today: string): Promise<void> {
    const id = this.sheetId();
    if (!id) throw new Error('No sheet loaded.');
    const sheet = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today }),
    );
    if (this.sheetId() === sheet.id) this.show(sheet);
  }

  /** Archive the active sheet (a steward only). */
  async archive(): Promise<void> {
    const id = this.sheetId();
    if (!id) throw new Error('No sheet loaded.');
    const sheet = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/archive`, null),
    );
    if (this.sheetId() === sheet.id) this.show(sheet);
  }

  /** Clone the active sheet to another id never used (a steward only); gives back that id. */
  async cloneTo(to: string): Promise<string> {
    const id = this.sheetId();
    if (!id) throw new Error('No sheet loaded.');
    const made = await firstValueFrom(
      this.http.post<{ to: string }>(`/api/sheets/${encodeURIComponent(id)}/clone`, { to }),
    );
    return made.to;
  }

  private show(sheet: SheetView): void {
    this.sheetId.set(sheet.id);
    this.sheetToday.set(sheet.today);
    this.archived.set(sheet.archived);
    this.lastBatch.set(sheet.lastBatch);
  }
}
import { HttpInterceptorFn } from '@angular/common/http';
import { inject } from '@angular/core';
import { Session } from './session';

/** The header that tells the server who is signed in, so it can record who made each change. */
export const USER_HEADER = 'X-User';

// Sends the signed-in user's name with every API request. The name is URI-encoded, since a header
// carries only plain ASCII; the server decodes it.
export const userHeader: HttpInterceptorFn = (req, next) => {
  const user = inject(Session).user();
  return next(user ? req.clone({ setHeaders: { [USER_HEADER]: encodeURIComponent(user) } }) : req);
};

/** The header that tells the server the date this screen shows the sheet as of. */
export const AS_OF_HEADER = 'X-As-Of';

// Sends the screen's as-of date, while one is set, with every API request: the server answers reads
// as the sheet stood at the end of that day and refuses every change.
export const asOfHeader: HttpInterceptorFn = (req, next) => {
  const asOf = inject(Session).asOf();
  return next(asOf ? req.clone({ setHeaders: { [AS_OF_HEADER]: asOf } }) : req);
};
import { Component, inject } from '@angular/core';
import { Route, Router, RouterLink, RouterOutlet } from '@angular/router';

// Minimal base shell. It renders the nav bar and the routed page. The nav comes from the ROUTER'S
// OWN CONFIG — every route carrying `data.section` becomes a link — so the shell holds no list of
// pages and is not edited when one is added. Every observable element carries a stable data-testid.
@Component({
  selector: 'app-root',
  imports: [RouterOutlet, RouterLink],
  template: `
    <div data-testid="app-root">
      <nav data-testid="app-nav">
        @for (r of nav; track r.path) {
          <a
            [routerLink]="'/' + r.path"
            [attr.data-testid]="'nav-' + r.data!['section']"
            >{{ r.data!['label'] }}</a
          >
        }
      </nav>
      <main data-testid="app-home">
        <router-outlet />
      </main>
    </div>
  `,
})
export class App {
  protected readonly nav: Route[] = inject(Router)
    .config.filter((r) => !!r.data?.['section'])
    .sort(
      (a, b) =>
        ((a.data?.['order'] as number) ?? 0) - ((b.data?.['order'] as number) ?? 0) ||
        String(a.data?.['section']).localeCompare(String(b.data?.['section'])),
    );
}
import { Component, inject, signal } from '@angular/core';
import { Session } from '../../core/session';
import { AuditViewer } from '../audit/audit-viewer';
import { People } from '../people/people';
import { TreeSearch } from '../search/tree-search';
import { SettingStore } from '../settings/settings';

// The one screen: sign in by name, then load a sheet by id.
@Component({
  selector: 'app-home',
  imports: [AuditViewer, People, TreeSearch],
  template: `
    @if (session.user(); as user) {
      <p>Signed in as <strong data-testid="current-user">{{ user }}</strong></p>

      <form (submit)="load($event)">
        <label for="sheet-id">Sheet id</label>
        <input
          id="sheet-id"
          data-testid="sheet-id-input"
          [value]="sheetInput()"
          (input)="sheetInput.set(value($event)); sheetError.set(null)"
        />
        <button type="submit" data-testid="sheet-load">Load</button>
      </form>
      @if (sheetError(); as error) {
        <p role="alert" data-testid="sheet-load-error">{{ error }}</p>
      }

      @if (session.sheetId(); as sheet) {
        <p>Sheet <strong data-testid="sheet-current-id">{{ sheet }}</strong></p>
        <p>Today <strong data-testid="sheet-today">{{ session.today() }}</strong></p>
        <form (submit)="saveToday($event)">
          <label for="sheet-today-date">Change today</label>
          <input
            id="sheet-today-date"
            type="date"
            data-testid="sheet-today-input"
            [value]="todayInput()"
            (input)="todayInput.set(value($event)); todayError.set(null)"
          />
          <button type="submit" data-testid="sheet-today-save">Set today</button>
        </form>
        <p>
          Archived <strong data-testid="sheet-archived">{{ session.archived() ? 'yes' : 'no' }}</strong>
          <button type="button" data-testid="sheet-archive" (click)="archive()">Archive sheet</button>
        </p>
        <p>Parent sheet <strong data-testid="sheet-parent">{{ settings.parent() }}</strong></p>
        <form (submit)="cloneSheet($event)">
          <label for="sheet-clone-to">Clone to sheet id</label>
          <input
            id="sheet-clone-to"
            data-testid="sheet-clone-to"
            [value]="cloneInput()"
            (input)="cloneInput.set(value($event)); todayError.set(null)"
          />
          <button type="submit" data-testid="sheet-clone">Clone sheet</button>
          Last clone made <strong data-testid="sheet-cloned-to">{{ clonedTo() }}</strong>
        </form>
        @if (todayError(); as error) {
          <p role="alert" data-testid="sheet-error">{{ error }}</p>
        }
        <form (submit)="setAsOf($event)">
          <label for="asof-date">Show as of</label>
          <input
            id="asof-date"
            type="date"
            data-testid="asof-date"
            [value]="asOfInput()"
            (input)="asOfInput.set(value($event)); asOfError.set(null)"
          />
          <button type="submit" data-testid="asof-set">Set as of</button>
          <button type="button" data-testid="asof-clear" (click)="clearAsOf()">Clear as of</button>
          As of <strong data-testid="sheet-asof">{{ session.asOf() ?? '' }}</strong>
        </form>
        @if (asOfError(); as error) {
          <p role="alert" data-testid="asof-error">{{ error }}</p>
        }
        <app-people />
        <app-tree-search />
        <app-audit-viewer />
      } @else {
        <p data-testid="home-empty">No sheet loaded.</p>
      }
    } @else {
      <form (submit)="signIn($event)">
        <label for="signin-name">Name</label>
        <input
          id="signin-name"
          data-testid="signin-name"
          [value]="nameInput()"
          (input)="nameInput.set(value($event)); signinError.set(null)"
        />
        <button type="submit" data-testid="signin-submit">Sign in</button>
      </form>
      @if (signinError(); as error) {
        <p role="alert" data-testid="signin-error">{{ error }}</p>
      }
    }
  `,
})
export class Home {
